void copy_bytes(char* destination, char* source, size_t num_bytes) {
    // Copy the specified number of bytes from the source location to the destination location
    for (size_t i = 0; i < num_bytes; i++) {
        *(destination + i) = *(source + i);
    }
}

int main() {
    char buffer[1024]; // Create a buffer with enough space to hold the string "Hello"
    char* source = "Hello"; // Define a pointer to the string "Hello"
    size_t num_bytes = strlen(source); // Get the length of the string "Hello"

    copy_bytes(buffer, source, num_bytes); // Copy the string "Hello" to the buffer

    return 0;
}
```
