    int sales[12] = {0};
    for (int i = 0; i < 12; i++) {
        sales[i] += getMonthlySales();
    }
    printf("Quarterly Sales:\n");
    for (int i = 0; i < 4; i++) {
        int quarter_sales = 0;
        for (int j = i * 3; j < (i + 1) * 3; j++) {
            quarter_sales += sales[j];
        }
