    # Send a GET request to the server to retrieve the user's information
    response = requests.get('http://localhost:8000/user')

    # Check if the response is successful (status code 200)
    if response.status_code == 200:
        # If the response is successful, return the response JSON data
        return response.json()
    else:
        # If the response is not successful, raise an exception with the error message
        raise Exception('Failed to retrieve user information: {}'.format(response.text))

def get_admin():
    # Send a GET request to the server to retrieve the admin's information
    response = requests.get('http://localhost:8000/admin')

    # Check if the response is successful (status code 200)
    if response.status_code == 200:
        # If the response is successful, return the response JSON data
        return response.json()
    else:
        # If the response is not successful, raise an exception with the error message
        raise Exception('Failed to retrieve admin information: {}'.format(response.text))

