['Here's an example C code that reads the contents of a file into a buffer, calculates the checksum of the buffer, and saves the number of bytes read and the checksum to a file:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void) {
    // Open the input file in binary mode
    FILE *input_file = fopen("input.txt", "rb");

    // Check if the file was successfully opened
    if (input_file == NULL) {
        printf("Error: unable to open input file\n");
        return 1;
    }

    // Determine the size of the buffer needed to read the entire file
    fseek(input_file, 0L, SEEK_END);
    long file_size = ftell(input_file);
    rewind(input_file);

    // Allocate memory for the buffer
    char *buffer = malloc(sizeof(char) * file_size);

    // Read the entire file into the buffer
    fread(buffer, sizeof(char), file_size, input_file);

    // Calculate the checksum of the buffer
    int checksum = 0;
    for (int i = 0; i < file_size; i++) {
        checksum += buffer[i];
    }

    // If the checksum is 0, the buffer is empty
    if (checksum == 0) {
        printf("Buffer is empty\n");
    } else {
        // Save the number of bytes read and the checksum to a file
        FILE *output_file = fopen("output.txt", "wb");
        if (output_file != NULL) {
            fprintf(output_file, "%d %d\n", file_size, checksum);
            fclose(output_file);
        } else {
            printf("Error: unable to open output file\n");
        }
    }

    // Free the memory allocated for the buffer
    free(buffer);

    // Close the input file
    fclose(input_file);

    return 0;
}
```
This code uses `fopen()` to open a file in binary mode, `ftell()` to determine the size of the file, and `rewind()` to rewind the file pointer back to the beginning of the file. It then allocates memory for a buffer that is large enough to hold the entire contents of the file using `malloc()`.

It reads the entire file into the buffer using `fread()`, and calculates the checksum of the buffer using a simple algorithm that adds up the values of all the bytes in the buffer. If the checksum is 0, it means that the buffer is empty, so it prints a message indicating this.

Otherwise, it saves the number of bytes read and the checksum to a file using `fopen()` and `fprintf()`. It then frees the memory allocated for the buffer using `free()`, and closes the input file using `fclose()`.

