void executeCommand(char *command) {
    char buf[1024];
    FILE *fp;
    int status;

    // Open a pipe for reading and writing to the external command
    fp = popen(command, "r");

    // Read output from the pipe until EOF is reached
    while (fgets(buf, sizeof(buf), fp) != NULL) {
        printf("%s", buf);
    }

    // Close the pipe and check for errors
    status = pclose(fp);
    if (status == -1) {
        perror("Error executing command");
    }
}

int main() {
